ALTER TABLE events ADD COLUMN mode text NOT NULL DEFAULT 'items' CHECK(mode IN ('items','visit','packages'));
ALTER TABLE events ADD COLUMN recording_mode text NOT NULL DEFAULT 'opening' CHECK(recording_mode IN ('opening','leftovers-only'));
ALTER TABLE events ADD COLUMN walk_in_capacity int NOT NULL DEFAULT 0 CHECK(walk_in_capacity>=0);
ALTER TABLE events ADD COLUMN waitlist_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE events ADD COLUMN admissions_closed boolean NOT NULL DEFAULT false;
ALTER TABLE events ADD COLUMN package_label text NOT NULL DEFAULT '';
ALTER TABLE events ADD COLUMN recurrence_group_id uuid;
CREATE TABLE event_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,capacity int NOT NULL CHECK(capacity>0),CHECK(ends_at>starts_at));
CREATE TABLE allowance_policies(org_id uuid PRIMARY KEY REFERENCES organizations(id),period_days int NOT NULL DEFAULT 7 CHECK(period_days BETWEEN 1 AND 366),visits int NOT NULL DEFAULT 1 CHECK(visits BETWEEN 0 AND 100),per_member_visits int NOT NULL DEFAULT 0 CHECK(per_member_visits BETWEEN 0 AND 100),category_limits jsonb NOT NULL DEFAULT '{}',no_show_consumes boolean NOT NULL DEFAULT false,allow_overrides boolean NOT NULL DEFAULT true);
CREATE TABLE event_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),location_id uuid NOT NULL REFERENCES locations(id),event_id uuid NOT NULL REFERENCES events(id),household_id uuid NOT NULL REFERENCES households(id),slot_id uuid REFERENCES event_slots(id),collector_id uuid REFERENCES users(id),booked_by uuid NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN ('confirmed','waitlisted','checked-in','completed','cancelled','no-show')),walk_in boolean NOT NULL DEFAULT false,package_count int NOT NULL DEFAULT 1 CHECK(package_count>0),reference text NOT NULL UNIQUE,notes text NOT NULL DEFAULT '',override_reason text,request_key uuid NOT NULL,request_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),checked_in_at timestamptz,completed_at timestamptz,UNIQUE(booked_by,request_key));
CREATE UNIQUE INDEX event_household_active ON event_bookings(event_id,household_id) WHERE status NOT IN ('cancelled','no-show');
CREATE INDEX event_bookings_location ON event_bookings(location_id,event_id,status);
CREATE TABLE allowance_holds(booking_id uuid PRIMARY KEY REFERENCES event_bookings(id),org_id uuid NOT NULL REFERENCES organizations(id),household_id uuid NOT NULL REFERENCES households(id),period_start date NOT NULL,period_end date NOT NULL,visits int NOT NULL DEFAULT 1 CHECK(visits>=0),categories jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'held' CHECK(state IN ('held','consumed','released')),overridden boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX allowance_household_period ON allowance_holds(org_id,household_id,period_start,state);
ALTER TABLE orders ADD COLUMN household_id uuid REFERENCES households(id);
ALTER TABLE orders ADD COLUMN booking_id uuid REFERENCES event_bookings(id);
ALTER TABLE orders ADD COLUMN currency text NOT NULL DEFAULT 'EUR';
ALTER TABLE orders ADD COLUMN seller_snapshot jsonb NOT NULL DEFAULT '{}';
ALTER TABLE orders ADD COLUMN payment_mode text NOT NULL DEFAULT 'provider' CHECK(payment_mode IN ('provider','local-fixture'));
CREATE TABLE seller_settings(org_id uuid PRIMARY KEY REFERENCES organizations(id),enabled boolean NOT NULL DEFAULT false,mode text NOT NULL DEFAULT 'disabled' CHECK(mode IN ('disabled','local-fixture')),destination_label text NOT NULL DEFAULT '',currency text NOT NULL DEFAULT 'EUR',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event_allocations(event_id uuid NOT NULL REFERENCES events(id),item_id uuid NOT NULL REFERENCES items(id),opening_qty int NOT NULL DEFAULT 0 CHECK(opening_qty>=0),added_qty int NOT NULL DEFAULT 0 CHECK(added_qty>=0),returned_qty int CHECK(returned_qty>=0),distributed_qty int CHECK(distributed_qty>=0),loss_qty int CHECK(loss_qty>=0),discrepancy_qty int CHECK(discrepancy_qty>=0),notes text NOT NULL DEFAULT '',PRIMARY KEY(event_id,item_id));
CREATE TABLE event_closeouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL UNIQUE REFERENCES events(id),request_hash text NOT NULL,recording_mode text NOT NULL CHECK(recording_mode IN ('opening','leftovers-only')),report jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),confirmed_at timestamptz NOT NULL DEFAULT now());
